 document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));
 const sx=sexNote(selected),sexHTML=sx?`<div class="sex-note"><h3>FRAU & MANN</h3><p>${esc(sx.text)}</p>${sourceLink(sx.source)}${sx.female?'<button class="secondary female-link" data-open-female>♀ Im weiblichen 3D-Modell ansehen</button>':''}</div>`:'';
 if(tab==='anatomy')$('detail-content').innerHTML=(p?`<h3>WAS IST DAS?</h3><p>${esc(p[3])}</p><h3>AUFGABE IM KÖRPER</h3><p>${esc(p[4])}</p><h3>ANATOMISCHER ZUSAMMENHANG</h3><p>${esc(s.name)}${n.side?' · Körperseite '+esc(n.side):''}. ${n.modifier?'Das ausgewählte Modell zeigt einen Teilbereich; die Funktionsbeschreibung bezieht sich auf die übergeordnete Struktur.':'Die Form zeigt die Lage und Ausdehnung im Referenzkörper.'}</p>`:`<h3>ZUORDNUNG</h3><p>${esc(n.de)} gehört zum System „${esc(s.name)}“.</p><h3>AUFGABE DES SYSTEMS</h3><p>${esc(s.info)}</p><div class="notice">Für dieses Teilmodell liegt noch keine eigene Detailerklärung vor. Die Beschreibung oben gilt für das Körpersystem, nicht speziell für dieses Einzelteil.</div>`)+sexHTML;
 if(tab==='health')$('detail-content').innerHTML=`<h3>${esc(h.title.toUpperCase())}</h3><p>${esc(h.text)}</p><div class="alert-box"><h3 style="margin-top:0">WANN HILFE NÖTIG IST</h3><p>${esc(h.warning)}</p></div><p class="small">Allgemeine Orientierung für diese Region. Keine Aussage darüber, ob diese Struktur deine Beschwerden verursacht. Medikamente nur passend zu Vorerkrankungen und anderen Mitteln mit Praxis oder Apotheke klären.</p>${sourceLink(h.source)}`;
if(tab==='notes'){$('detail-content').innerHTML=pro.notesHTML(selected);pro.bindNotes(selected)}
 if(tab==='sources')$('detail-content').innerHTML=`<h3>ANATOMIE & MODELL</h3>${sourceLink(p?p[5]:s.source)}${sx?sourceLink(sx.source):''}${sourceLink('dataset')}<h3>BESCHWERDEN</h3>${sourceLink(h.source)}<h3>ORIGINALBEZEICHNUNG</h3><p>${esc(selected.en)}<br><span class="small">FMA/BodyParts3D: ${esc(selected.id)}</span></p><p class="small">Stand des Quellenabgleichs: 07.09.2026. Übersetzung und Kurztexte ohne ärztliche Abnahme. Netzvereinfachung für mobile Darstellung.</p>`;
 $('isolate').disabled=!selected.mesh;$('focus').disabled=!selected.mesh;$('isolate').innerHTML=isolated?'Gesamten Körper anzeigen <span>⤢</span>':'Struktur isolieren <span>⤢</span>';
