document.querySelectorAll('[data-tab]').forEach((b,i)=>{b.onclick=()=>{tab=b.dataset.tab;renderDetail()};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const bs=[...document.querySelectorAll('[data-tab]')];const next=bs[(i+(e.key==='ArrowRight'?1:bs.length-1))%bs.length];next.focus();next.click()}}});renderDetail();
function select(m,focus=false){female.exit(true);selected=m;try{history.replaceState(null,'','#'+m.id)}catch{}visible.add(m.system);$('selected-label').hidden=false;$('selected-label').textContent=m.label.de;renderSystems();applyVisibility();renderDetail();if(focus&&m.mesh)focusSelected();if(innerWidth<=850)$('systems-panel').classList.remove('open')}
function renderSystems(){const counts={};for(const m of catalog.meshes)counts[m.system]=(counts[m.system]||0)+1;$('systems').innerHTML=Object.entries(systems).map(([id,s])=>`<label class="system-row"><span class="dot" style="background:${s.color}"></span><span class="system-name">${s.name}</span><small>${counts[id]||0}</small><input type="checkbox" aria-label="${s.name} anzeigen" role="switch" data-system="${id}" ${visible.has(id)?'checked':''}></label>`).join('');document.querySelectorAll('[data-system]').forEach(x=>x.onchange=()=>{x.checked?visible.add(x.dataset.system):visible.delete(x.dataset.system);if(!x.checked&&selected?.system===x.dataset.system){selected=null;$('selected-label').hidden=true}isolated=false;applyVisibility();renderDetail();document.querySelectorAll('[data-preset]').forEach(b=>b.classList.remove('active'))})}
function materialColor(m){if(m.system==='vessels')return /vein|vena|sinus/.test(m.en)?'#688da9':'#b86562';if(m.en.includes('cartilage')||m.en.includes('disk')||m.en.includes('tendon'))return '#c9d7d4';if(m.en.includes('liver'))return '#a06555';if(m.en.includes('kidney'))return '#aa655f';return systems[m.system].color}
function applyVisibility(){const cut=$('cutaway').checked,xray=$('xray').checked;for(const m of meshes){const d=m.userData;let show=visible.has(d.system);if(isolated)show=selected?.id===d.id;else if(cut&&d.system==='muscles'&&d.center[0]<.008)show=false;if(selected?.id===d.id)show=true;m.visible=show;const is=selected?.id===d.id;m.material.color.set(is?'#58818a':materialColor(d));m.material.emissive.set(is?'#204452':'#000000');m.material.emissiveIntensity=is?.12:0;m.material.transparent=!is&&xray&&!isolated;m.material.opacity=m.material.transparent?.16:1;m.material.depthWrite=!m.material.transparent;}
 pro.applyClip();if(female.isActive()){for(const m of meshes)m.visible=false;female.apply();dirty=true;return}const shown=meshes.filter(m=>m.visible).length;$('count').textContent=shown+' / '+catalog.meshes.length+' Teilmodelle sichtbar';dirty=true;}
$('cutaway').onchange=applyVisibility;$('xray').onchange=applyVisibility;
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{visible=new Set(b.dataset.preset==='all'?Object.keys(systems).filter(x=>x!=='skin'):b.dataset.preset==='bones'?['bones']:['heart','respiratory','digestive','urinary','endocrine','reproductive','lymphatic']);isolated=false;selected=null;$('selected-label').hidden=true;renderSystems();applyVisibility();renderDetail();$('isolate').disabled=true;$('focus').disabled=true;document.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('active',x===b));resetCamera()});
function resetCamera(){if(!camera)return;const tan=Math.tan(THREE.MathUtils.degToRad(17.5));const distance=THREE.MathUtils.lerp(Math.max(3.2,.82/(2*tan*freeAspect)),Math.max((grid.h+.5)/(2*tan),(grid.w+.35)/(2*tan*freeAspect)),explode);controls.target.set(0,0,0);camera.position.set(0,0,distance);controls.update();dirty=true;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='front'));$('view-label').textContent='Vorderansicht'}
function focusSelected(){if(!selected?.mesh)return;if(!isolated&&!$('xray').checked){$('xray').checked=true;applyVisibility()}const m=selected.mesh;controls.target.copy(m.position);const sz=Math.max(...selected.size)*m.scale.x;camera.position.copy(m.position).add(new THREE.Vector3(.1,.04,Math.max(sz*2.5,.24)));controls.update();dirty=true}
$('focus').onclick=()=>female.isActive()?female.focus():focusSelected();$('isolate').onclick=()=>{if(female.isActive()){female.isolate();return}isolated=!isolated;if(isolated){explode=0;$('explode').value=0;$('explode-value').textContent='0 %';layout();focusSelected()}else resetCamera();applyVisibility();renderDetail()};
$('reset').onclick=()=>{if(quiz)endQuiz(true);pro.reset();female.exit(true);try{history.replaceState(null,'',location.pathname+location.search)}catch{}isolated=false;selected=null;explode=0;$('explode').value=0;$('explode-value').textContent='0 %';$('selected-label').hidden=true;$('xray').checked=false;$('cutaway').checked=true;visible=new Set(Object.keys(systems).filter(s=>s!=='skin'));layout();resetCamera();renderSystems();applyVisibility();$('latin').textContent='Corpus humanum';$('german').textContent='Der menschliche Körper';$('detail-meta').textContent='Eine Struktur im Modell oder in der Suche auswählen.';$('detail-system').textContent='ANATOMISCHER ATLAS';$('detail-id').textContent='3D';$('isolate').disabled=true;$('focus').disabled=true;renderDetail()};
